package io.github.jesterportfolio.hearth.economy;
import org.junit.jupiter.api.Test;
import static org.junit.jupiter.api.Assertions.*;
import static io.github.jesterportfolio.hearth.economy.EconomyContent.*;
import static io.github.jesterportfolio.hearth.economy.EconomyEngine.*;
import java.util.*;
final class MarketRoutingTest{
 final EconomyContent demo=EconomyEngineTest.demo();final UUID realm=UUID.randomUUID();
 EconomyContent simple(List<Route> routes,List<Facility> facilities,Map<Key,Long> demand){return new EconomyContent(List.of("a","b","c"),Map.of("ore",new Good("ore","IRON_ORE",100,100),"ingot",new Good("ingot","IRON_INGOT",300,100)),demand,facilities,routes,Map.of(),demo.policy(),5000,"PAUSE",8,0);}
 Map<Key,Long> stocks(EconomyContent c,long a,long b,long d){var result=new HashMap<Key,Long>();for(var key:c.cells())result.put(key,key.good().equals("ore")?switch(key.region()){case "a"->a;case "b"->b;default->d;}:100L);return result;}
 State state(EconomyContent c,Map<Key,Long> stock){var rows=new HashMap<Key,Market>();stock.forEach((k,v)->rows.put(k,new Market(v,c.goods().get(k.good()).base(),0)));return new State(0,rows,List.of(),List.of());}
 @Test void full_destination_stops_unnecessary_shipments_and_legacy_behavior_is_unchanged(){var c=simple(List.of(new Route("ab","a","b","ore",10,2)),List.of(),Map.of());var s=state(c,stocks(c,100,100,100));assertEquals(1,advance(realm,c,s).departed().size());assertTrue(advance(realm,c,s,new MarketRouting.Policy(2500,2)).departed().isEmpty());}
 @Test void pending_arrivals_are_counted_before_another_supplier_sends(){var c=simple(List.of(new Route("ab","a","b","ore",100,3)),List.of(),Map.of());var stock=stocks(c,100,0,100);var s=state(c,stock);var transit=List.of(new Shipment(UUID.randomUUID(),"ab","a","b","ore",90,3));var result=MarketRouting.plan(c,s,1,stock,transit,new MarketRouting.Policy(0,1));assertEquals(10L,result.get("ab"));}
 @Test void source_retains_local_consumption_and_manufacturing_inputs(){var facility=new Facility("smelter","a","ingot",20,Map.of("ore",2L),10000);var c=simple(List.of(new Route("ab","a","b","ore",100,2)),List.of(facility),Map.of(new Key("a","ore"),5L));var stock=stocks(c,100,0,100);var result=MarketRouting.plan(c,state(c,stock),1,stock,List.of(),new MarketRouting.Policy(2500,2));assertEquals(10L,result.get("ab"));}
 @Test void scarce_source_capacity_is_shared_proportionally(){var c=simple(List.of(new Route("ab","a","b","ore",100,2),new Route("ac","a","c","ore",100,2)),List.of(),Map.of());var stock=stocks(c,51,0,0);var result=MarketRouting.plan(c,state(c,stock),1,stock,List.of(),new MarketRouting.Policy(0,1));assertEquals(51L,result.values().stream().mapToLong(Long::longValue).sum());assertTrue(Math.abs(result.get("ab")-result.get("ac"))<=1);var next=MarketRouting.plan(c,state(c,stock),2,stock,List.of(),new MarketRouting.Policy(0,1));assertNotEquals(result,next);}
 @Test void multiple_sources_cannot_overfill_one_destination(){var c=simple(List.of(new Route("ab","a","b","ore",100,2),new Route("cb","c","b","ore",100,2)),List.of(),Map.of());var stock=stocks(c,100,90,100);var result=MarketRouting.plan(c,state(c,stock),1,stock,List.of(),new MarketRouting.Policy(0,1));assertEquals(10L,result.values().stream().mapToLong(Long::longValue).sum());}
 @Test void managed_shipping_preserves_total_items_and_never_exceeds_route_or_stock_caps(){var c=simple(List.of(new Route("ab","a","b","ore",7,3),new Route("ac","a","c","ore",5,2)),List.of(),Map.of());var s=state(c,stocks(c,100,0,0));long total=s.markets().values().stream().mapToLong(Market::stock).sum();for(int i=0;i<200;i++){var step=advance(realm,c,s,new MarketRouting.Policy(2500,2));assertTrue(step.departed().stream().allMatch(x->x.quantity()<=(x.route().equals("ab")?7:5)));s=step.state();assertEquals(total,s.markets().values().stream().mapToLong(Market::stock).sum()+s.shipments().stream().mapToLong(Shipment::quantity).sum());assertTrue(s.markets().get(new Key("a","ore")).stock()>=25);}}
 @Test void routing_is_deterministic_and_never_mutates_input_maps(){var c=simple(List.of(new Route("ab","a","b","ore",10,1)),List.of(),Map.of());var stock=stocks(c,100,0,0);var before=Map.copyOf(stock);var s=state(c,stock);assertEquals(MarketRouting.plan(c,s,1,stock,List.of(),new MarketRouting.Policy(0,1)),MarketRouting.plan(c,s,1,stock,List.of(),new MarketRouting.Policy(0,1)));assertEquals(before,stock);}
 @Test void bounded_policy_and_maximum_stock_inputs_are_handled(){assertThrows(IllegalArgumentException.class,()->new MarketRouting.Policy(-1,1));assertThrows(IllegalArgumentException.class,()->new MarketRouting.Policy(10001,1));assertThrows(IllegalArgumentException.class,()->new MarketRouting.Policy(0,17));var c=simple(List.of(new Route("ab","a","b","ore",1000000,1000)),List.of(),Map.of());var stock=stocks(c,MAX_STOCK,MAX_STOCK,MAX_STOCK);assertEquals(0L,MarketRouting.plan(c,state(c,stock),1,stock,List.of(),new MarketRouting.Policy(10000,16)).get("ab"));}
}
